mapper.select:
select lvp.id, prop_id, prop_name, total_score, total_diamonds, total_ticket, current_diamonds, before_ticket, from_user_id,
lvp.p_user_id, p_user_name, to_user_id, lu.nick_name, FROM_UNIXTIME(lvp.create_time) create_time , create_date, create_y, create_m, create_d,
create_w, num, video_id, group_id, is_red_envelope, msg, ActionStatus, ErrorInfo, ErrorCode, create_ym, is_private,
from_ip, is_coin from ${dbLive}.live_video_prop lvp left join ${dbLive}.live_user lu on lvp.to_user_id = lu.id


		and lvp.p_user_id = #{pUserId}


		and lvp.to_user_id = #{toUserId}


		and lvp.prop_name = #{propName}


		and FROM_UNIXTIME(lvp.create_time) >= #{startTime}
		and FROM_UNIXTIME(lvp.create_time) <= #{endTime}

select lvp.id, prop_id, prop_name, total_score, total_diamonds, total_ticket, current_diamonds, before_ticket, from_user_id,
lvp.p_user_id, p_user_name, to_user_id, lu.nick_name, FROM_UNIXTIME(lvp.create_time) create_time , create_date, create_y, create_m, create_d,
create_w, num, video_id, group_id, is_red_envelope, msg, ActionStatus, ErrorInfo, ErrorCode, create_ym, is_private,
from_ip, is_coin from ${dbLive}.live_video_prop lvp left join cx_live.live_user lu on lvp.to_user_id = lu.id


		and lvp.p_user_id = #{pUserId}


		and lvp.to_user_id =#{toUserId}


		and lvp.prop_name =#{propName}


		and FROM_UNIXTIME(lvp.create_time) >= #{startTime}
		and FROM_UNIXTIME(lvp.create_time) <= #{endTime}

select sum(total_diamonds) countTotal
from ${dbLive}.live_video_prop

	and prop_id > 0

		and p_user_id = #{pUserId}


		and to_user_id =#{toUserId}


		and FROM_UNIXTIME(create_time) >= #{startTime}
		and FROM_UNIXTIME(create_time) <= #{endTime}

SELECT p_user_id as pUserId, p_user_name as pUserName, to_user_id as toUserId, SUM( total_diamonds ) as totalDiamonds FROM ${dbLive}.live_video_prop
and to_user_id NOT IN ( '0', '-1' ) and p_user_id IN ( SELECT id FROM ${dbMain}.member_info WHERE status in ('2','0'))
and to_user_id =#{toUserId}
and create_date = #{testAccountCreateTime}
GROUP BY p_user_id, to_user_id ORDER BY to_user_id

SELECT SUM( total_diamonds ) as testAccountPorpTotal FROM ${dbLive}.live_video_prop
and to_user_id NOT IN ( '0', '-1' ) and p_user_id IN ( SELECT id FROM ${dbMain}.member_info WHERE STATUS = '2' )
and to_user_id =#{toUserId}
and create_date = #{testAccountCreateTime}
